SINA_SMART["biophys1-optics"] = {"lecture":"biophys1-optics","title":"Geometrical optics applied to vision","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"biophys1-optics:s0","text":"Describe and explain: The big picture","topic":"The big picture","sec":0,"importance":"standard","highYield":"insufficient-source"},{"id":"biophys1-optics:e0","text":"Snell-Descartes: n₁ sin i₁ = n₂ sin i₂; n = c/v.","topic":"Basic optics","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biophys1-optics:e1","text":"Visible light 380-700 nm; c = 3×10⁸ m/s.","topic":"Basic optics","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biophys1-optics:e2","text":"Diopter power P = (n₂ − n₁)/r, in dioptres; + converging, − diverging.","topic":"Basic optics","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biophys1-optics:e3","text":"Eye: cornea +48 and −6 D, lens +8 and +14 D; total ≈ 64 D.","topic":"Dioptrics of the normal eye","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"biophys1-optics:e4","text":"Accommodation: ciliary contraction, zonule relaxes, lens bulges.","topic":"Dioptrics of the normal eye","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"biophys1-optics:e5","text":"Near point ~10 cm (child), ≤ 25 cm (adult); presbyopia: > 25 cm, converging lenses.","topic":"Dioptrics of the normal eye","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"biophys1-optics:e6","text":"Diplopia → amblyopia; patch the healthy eye before age 6.","topic":"Binocular vision, acuity and ametropias","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"biophys1-optics:e7","text":"Normal acuity: 1′ = 10/10; VA = 1/α.","topic":"Binocular vision, acuity and ametropias","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"biophys1-optics:e8","text":"Myopia: image in front, diverging lens. Hyperopia: behind, converging lens.","topic":"Binocular vision, acuity and ametropias","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"biophys1-optics:e9","text":"Astigmatism: non-spherical cornea, cylindrical lens.","topic":"Binocular vision, acuity and ametropias","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1hmolzy":"a","1lq0hby":"a","guq3sf":"a","1ezkv0y":"a","kwlvwu":"a","p64ngx":"a","180xasr":"a","126hek3":"a","1lmdwoy":"a","bth82d":"a","1cs10fo":"a","1cot5gk":"a","uypl55":"a","1naaay4":"a","ss0y5d":"x"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"biophys1-optics:s0":{"s":0,"u":["Geometrical optics studies how light rays travel through transparent media, based on Fermat's principle (1657) and the Snell-Descartes laws of reflection and refraction.","Applied to the eye, it explains how an image forms on the retina, how accommodation works, and how refractive errors are corrected."],"dp":[]},"biophys1-optics:e0":{"s":1,"u":["Snell-Descartes: n₁ sin i₁ = n₂ sin i₂; n = c/v.","A diopter is a surface separating two media of different n; at it, light is partly reflected and partly refracted (n₁ sin i₁ = n₂ sin i₂)."],"dp":[]},"biophys1-optics:e1":{"s":1,"u":["Visible light 380-700 nm; c = 3×10⁸ m/s.","Visible light: 380-700 nm ; speed in vacuum c = 3 × 10⁸ m/s .","A light ray is the path light follows (straight in a homogeneous medium)."],"dp":[]},"biophys1-optics:e2":{"s":1,"u":["Diopter power P = (n₂ − n₁)/r, in dioptres; + converging, − diverging.","Power of a diopter P = (n₂ − n₁)/r (r in m; unit dioptre, D): positive = converging, negative = diverging."],"dp":[]},"biophys1-optics:e3":{"s":2,"u":["Eye: cornea +48 and −6 D, lens +8 and +14 D; total ≈ 64 D.","Four surfaces: anterior cornea (n = 1.377, r = 7.8 mm): +48 D ; posterior cornea (aqueous n = 1.337, r = 6.5 mm): −6 D ; anterior lens (n = 1.42, r = 10 mm): +8 D ; posterior lens (r = 6 mm): +14 D ; total ≈ 64 D at rest ."],"dp":[{"h":"Why the cornea does most of the focusing","t":"Refraction depends on the jump in refractive index at a surface. Between air (1.0) and cornea (1.377) the jump is large, so the front of the cornea bends light by about 48 D, while inside the eye the indices of cornea, aqueous humour and lens are close, giving smaller powers. That is why reshaping the cornea (refractive surgery) can correct large errors, and why vision blurs underwater, where the air-cornea jump disappears. Source: the lecture's ocular diopters slides."}]},"biophys1-optics:e4":{"s":2,"u":["Accommodation: ciliary contraction, zonule relaxes, lens bulges.","Accommodation : the retina cannot move, so to see near objects the eye increases its power: the ciliary muscle contracts , the zonular fibres relax , and the lens becomes more convex."],"dp":[]},"biophys1-optics:e5":{"s":2,"u":["Near point ~10 cm (child), ≤ 25 cm (adult); presbyopia: > 25 cm, converging lenses.","Presbyopia : age-related lens hardening reduces accommodation ( converging lenses for near vision; it appears later in myopes.","The punctum remotum (far point) is seen without accommodation (infinity in the normal eye); the punctum proximum (near point) with maximal accommodation (~10 cm in young children, ≤ 25 cm in adults)."],"dp":[]},"biophys1-optics:e6":{"s":3,"u":["Diplopia → amblyopia; patch the healthy eye before age 6.","Diplopia : images on non-corresponding points (e.g. muscle imbalance); if persistent, the brain suppresses one eye, causing amblyopia (lazy eye), treatable if found before age 6 (treat the cause such as strabismus; patch the healthy eye ), irreversible after ~10."],"dp":[{"h":"Why amblyopia must be caught early","t":"The visual cortex wires itself to each eye during early childhood. If one eye sends a blurred or conflicting image, the brain learns to ignore it, and its connections weaken. Patching the good eye forces the brain to use the weak one while the system is still plastic; after about age 10 the wiring is fixed and glasses can no longer restore vision. Source: the lecture's diplopia and amblyopia slides."}]},"biophys1-optics:e7":{"s":3,"u":["Normal acuity: 1′ = 10/10; VA = 1/α.","Visual acuity = 1/α (α = smallest resolvable visual angle): a normal eye separates points at 1′ → 10/10 ; 5′ → 2/10; measured with optotype charts."],"dp":[]},"biophys1-optics:e8":{"s":3,"u":["Myopia: image in front, diverging lens. Hyperopia: behind, converging lens.","Hyperopia : image behind the retina (not powerful enough); virtual far point behind the eye; corrected with converging lenses.","Myopia : image in front of the retina (eye too powerful or too long); far point at a finite distance; corrected with diverging lenses (degree = 1/PR)."],"dp":[]},"biophys1-optics:e9":{"s":3,"u":["Astigmatism: non-spherical cornea, cylindrical lens.","Astigmatism : a non-spherical surface (usually the cornea) distorts images; corrected with cylindrical lenses."],"dp":[]}},"meta":{"1hmolzy":{"a":"recall","vg":"biophys1-optics:e1/recall/1"},"1lq0hby":{"a":"recall","vg":"biophys1-optics:e2/recall/1"},"guq3sf":{"a":"recall","vg":"biophys1-optics:e3/recall/1"},"1ezkv0y":{"a":"recall","vg":"biophys1-optics:e3/recall/2"},"kwlvwu":{"a":"recall","vg":"biophys1-optics:e4/recall/1"},"p64ngx":{"a":"recall","vg":"biophys1-optics:e5/recall/1"},"180xasr":{"a":"recall","vg":"biophys1-optics:e5/recall/2"},"126hek3":{"a":"relationship","vg":"biophys1-optics:e5/relationship/1"},"1lmdwoy":{"a":"recall","vg":"biophys1-optics:e6/recall/1"},"bth82d":{"a":"recall","vg":"biophys1-optics:e7/recall/1"},"1cs10fo":{"a":"recall","vg":"biophys1-optics:e8/recall/1"},"1cot5gk":{"a":"recall","vg":"biophys1-optics:e8/recall/2"},"uypl55":{"a":"recall","vg":"biophys1-optics:e8/recall/2"},"1naaay4":{"a":"recall","vg":"biophys1-optics:e9/recall/1"}},"explRev":"76e11d6ce9ac"};
